#[test]
fn matches_the_c_implementation() {
    let mut random = Random(0x9e37_79b9_7f4a_7c15);
    let mut average = Ravg::default();
    let mut now = 5 * u64::from(HALF_LIFE) + 12345;
    for &(step, value, offset, expected) in &GOLDEN {
        let mut drawn = random.next() % (3 * u64::from(HALF_LIFE));
        if random.next().is_multiple_of(4) {
            drawn %= 50_000;
        }
        assert_eq!(drawn, step);
        now += drawn;
        let drawn = if random.next().is_multiple_of(3) {
            0
        } else {
            random.next() % 2048
        };
        assert_eq!(drawn, value);
        accumulate(&mut average, value, now, HALF_LIFE);
        let drawn = random.next() % (2 * u64::from(HALF_LIFE));
        assert_eq!(drawn, offset);
        assert_eq!(read(&average, now + offset, HALF_LIFE), expected);
        // The fast path agrees wherever it applies, and falls back elsewhere.
        assert_eq!(read_fast(&average, now + offset, HALF_LIFE), expected);
        assert_eq!(
            read_fast(&average, now, HALF_LIFE),
            read(&average, now, HALF_LIFE)
        );
    }
}

#[test]
fn constant_input_converges_and_halves() {
    let half = u64::from(HALF_LIFE);
    let mut average = Ravg::default();
    accumulate(&mut average, 100, 0, HALF_LIFE);
    let settled = read(&average, 20 * half, HALF_LIFE);
    let one = 100_u64 << FRAC_BITS;
    assert!(settled.abs_diff(one) < one / 1000, "{settled} vs {one}");
    // Stopping halves the average over each half-life.
    accumulate(&mut average, 0, 20 * half, HALF_LIFE);
    let later = read(&average, 21 * half, HALF_LIFE);
    assert!(
        later.abs_diff(settled / 2) < one / 1000,
        "{later} vs {}",
        settled / 2
    );
    // Accumulating twice at one time changes only the value.
    let before = average;
    accumulate(&mut average, 7, 20 * half, HALF_LIFE);
    assert_eq!(
        (average.old, average.cur, average.val),
        (before.old, before.cur, 7)
    );
}
